'use strict';
function extendCampaign(regions,addPhase){
 regions.push(...[['Porto das novas rotas','Inferência e retomada'],['Vila dos elos','Coesão e ambiguidade'],['Relógios da memória','Tempo e narrativas'],['Fortaleza das regras','Condições e exceções'],['Jardim das intenções','Intenções e sentimentos'],['Teatro das perspectivas','Vozes e narradores'],['Ateliê das palavras','Nuances do vocabulário'],['Ilha dos símbolos','Poesia e simbolismo'],['Biblioteca dos gêneros','Finalidade e gênero'],['Redação da vila','Notícias e enquadramento'],['Praça dos registros','Interpretar registros'],['Observatório das amostras','Comparações justas'],['Câmara das suposições','Pressupostos e conclusões'],['Tribuna das respostas','Contra-argumentos'],['Rede das mensagens','Verificação de mensagens'],['Galeria das promessas','Persuasão e escolhas'],['Trilhas da incerteza','Graus de certeza'],['Assembleia das soluções','Conciliar interesses'],['Oficina das investigações','Planejar investigações'],['Horizonte da Ana Carla','Síntese e autonomia']].map(([name,skill])=>({name,skill})));
 addPhase(20,[
 ['O porto do outro lado','Após acender o primeiro farol, o grupo encontrou uma carta no cais.|“Além da enseada há outra vila. O barco leva visitantes, mas é preciso reservar lugar até a véspera”, dizia a carta.|Nilo queria partir no sábado; a oficina ainda estaria aberta na sexta para fazer reservas.','Qual ação atende ao plano de Nilo?','Reservar até sexta para viajar no sábado.|Reservar ao chegar ao barco no sábado.|Esperar o barco partir antes de reservar.',[1,2],'Relacione “véspera” ao dia pretendido.','A véspera é o dia anterior; planejar exige relacionar regra e data.'],
 ['O recado que faltava','Lia deixou no mural: “Tragam os mapas corrigidos para a reunião”.|Ravi tinha um mapa antigo e outro com a nova ponte marcada.|O conselho discutiria rotas que utilizam a ponte inaugurada naquela semana.','Qual mapa atende melhor ao pedido?','O que inclui a nova ponte.|O antigo, por já ter sido usado.|Os dois são necessariamente iguais.',[0,1,2],'Que informação torna o mapa adequado ao objetivo da reunião?','Uma escolha depende da atualização necessária, não apenas da familiaridade.'],
 ['A mala na entrada','Na sala de visitas, havia uma mala junto à porta.|A visitante consultava o horário do barco e conferia se havia guardado seus objetos.|O texto não informa o destino de sua viagem.','Qual inferência está mais apoiada?','Ela se preparava para uma possível partida.|Ela certamente iria para a gruta.|Ela estava desfazendo a mala para morar ali.',[0,1],'Diferencie preparação provável de destino desconhecido.','Uma inferência deve preservar o que continua sem informação.'],
 ['O mapa emprestado','Ravi emprestou um mapa a Lia até a manhã seguinte.|Ela anotou o caminho em seu próprio caderno e colocou o mapa novamente no envelope de Ravi.|Antes de sair, deixou o envelope na mesa dele.','O que as ações de Lia sugerem?','Ela guardou as informações e devolveu o empréstimo.|Ela decidiu levar o mapa indefinidamente.|Ela apagou o caminho do caderno.',[1,2],'Compare o destino do mapa com o destino das anotações.','Ações relacionadas podem revelar o cumprimento de um combinado.'],
 ['Dois avisos de partida','O primeiro aviso previa partida às nove.|Uma atualização identificada pela barqueira mudou a saída para as dez, devido à manutenção.|Ravi chegou às oito e meia sem ter lido a atualização.','Qual informação deve orientar a espera de Ravi?','A atualização das dez, explicada pela manutenção.|O primeiro aviso, por ter sido publicado antes.|A hora em que Ravi chegou ao porto.',[0,1],'Qual documento atualiza o horário anterior?','Uma atualização identificada pode substituir uma previsão anterior.']
 ]);
 addPhase(21,[
 ['Eles não são os livros','As crianças levaram livros aos moradores da vila.|Eles agradeceram a visita e pediram uma nova roda de leitura.|Os livros ficaram na biblioteca comunitária.','Quem é retomado por “eles”?','Os moradores.|Os livros.|Somente uma criança.',[0,1],'Quem pode agradecer a visita e pedir uma roda?','O sentido das ações ajuda a resolver referências quando há vários nomes próximos.'],
 ['A proposta retomada','Lia sugeriu dividir a limpeza entre as equipes.|Isso permitiria que cada grupo cuidasse de uma área menor.|O conselho aprovou a divisão, mantendo uma revisão final conjunta.','O que “isso” retoma?','Dividir a limpeza entre as equipes.|A revisão final ainda não mencionada.|A aprovação anterior do conselho.',[0,1],'Uma palavra pode retomar uma proposta inteira.','A coesão liga uma consequência à ideia apresentada antes.'],
 ['Uma frase com duas leituras','O bilhete dizia: “Lia viu Ravi com a luneta”.|Não havia imagem nem outra frase explicando quem segurava o instrumento.|Nilo pediu que o bilhete fosse reescrito.','Por que a reescrita seria útil?','A frase permite entender que Lia ou Ravi estava com a luneta.|A frase informa claramente que os dois tinham lunetas.|Não é possível saber quem são Lia e Ravi.',[0,1],'Teste dois sentidos de “com a luneta”.','Reconhecer ambiguidade é admitir mais de uma leitura que o texto não resolve.'],
 ['Aquela, não esta','Lia comparou duas cordas: a primeira era longa e a segunda, curta.|“Esta cabe no kit pequeno; aquela pode atravessar o rio”, disse.|Ravi colocou a corda curta no kit.','Qual corda “aquela” retoma?','A primeira, longa.|A segunda, curta.|Uma terceira corda não apresentada.',[0,1,2],'Relacione proximidade da referência e comprimento necessário.','A organização da frase e o sentido confirmam a referência.'],
 ['O grupo e seu plano','As equipes falaram com o conselho sobre a nova horta.|O conselho pediu que elas apresentassem medidas e uma lista de materiais.|As equipes voltaram à oficina para completar o projeto.','“Elas” se refere a quem?','Às equipes.|Às medidas.|À horta.',[0,1,2],'Quem recebe o pedido e pode completar o projeto?','As referências mantêm os participantes ligados ao longo de um texto.']
 ]);
 addPhase(22,[
 ['Um começo pelo final','O relato começa com Lia abrindo a exposição no domingo.|No parágrafo seguinte, ela lembra a sexta-feira em que separou os objetos.|Depois narra o sábado, quando montou as mesas.','Qual foi a ordem dos acontecimentos?','Separação, montagem, abertura.|Abertura, separação, montagem.|Montagem, abertura, separação.',[0,1,2],'Diferencie ordem do relato e ordem dos fatos.','Um narrador pode começar pelo final e voltar no tempo.'],
 ['Uma lembrança no caminho','Durante a caminhada de terça, Nilo lembrou a conversa de segunda.|Na conversa, Ravi havia explicado por que a trilha mudaria.|Ao fim da caminhada, Nilo encontrou o novo sinal.','Quando ocorreu a conversa explicativa?','Antes da caminhada.|Depois do encontro com o sinal.|Durante a caminhada de terça.',[0,1],'A lembrança acontece agora, mas o fato lembrado aconteceu quando?','O tempo de lembrar não é o mesmo tempo do acontecimento lembrado.'],
 ['Duas tarefas ao mesmo tempo','Enquanto Lia conferia as caixas, Ravi prendia as cordas no barco.|Depois que ambos terminaram, a barqueira autorizou a partida.|Nilo ficou esperando no cais durante a preparação.','Qual relação existe entre conferir caixas e prender cordas?','As tarefas ocorreram no mesmo período.|Conferir começou somente após a partida.|Prender cordas aconteceu no dia seguinte.',[0,1],'Observe “enquanto” e o requisito para partir.','A simultaneidade pode reunir tarefas que precisam terminar antes de outra etapa.'],
 ['O prazo da inscrição','O aviso foi publicado na segunda e encerrava inscrições na quinta às dezoito horas.|A oficina ocorreria no sábado pela manhã.|Lia encontrou o aviso na sexta.','O que as datas permitem concluir?','Lia encontrou o aviso depois do prazo, embora antes da oficina.|A inscrição continuava aberta por ser antes do sábado.|O prazo só começaria quando Lia lesse.',[0,1,2],'Não confunda data da atividade com limite de inscrição.','Prazos diferentes regulam ações diferentes.'],
 ['O plano antes da lembrança','Ravi escreveu hoje: “Amanhã terminaremos o telhado”.|Em seguida, contou que a madeira chegara dois dias antes.|O registro de hoje é de quarta-feira.','Quando está prevista a conclusão?','Quinta-feira.|Segunda-feira.|Quarta-feira, antes da escrita.',[0,2],'Use o dia do registro para interpretar “amanhã”.','Expressões temporais dependem do momento em que a mensagem é produzida.']
 ]);
 addPhase(23,[
 ['A exceção do depósito','Regra: o depósito abre às nove; em dias de entrega, abre às oito para a equipe.|Hoje havia entrega confirmada, mas nenhum aviso autorizava visitas antes das nove.|Lia fazia parte da equipe; Nilo era visitante.','Quem pode entrar às oito conforme a regra?','Lia, como integrante da equipe.|Nilo, pois qualquer entrega libera todos.|Nenhum deles, pois exceções anulam a regra.',[0,1,2],'A exceção se aplica a que pessoas?','Uma exceção tem um alcance definido, não libera automaticamente todos.'],
 ['Não basta ter a chave','A chave abre a porta da estufa.|Para entrar, porém, o visitante precisa também de acompanhamento.|Ravi tinha a chave e aguardava Lia, que seria sua acompanhante.','O que ainda falta para Ravi entrar?','O acompanhamento de Lia.|Outra chave idêntica.|A troca de todas as plantas.',[0,1,2],'Abrir a porta e estar autorizado são a mesma condição?','Um requisito material não substitui os demais requisitos de entrada.'],
 ['Ou um, ou outro?','O convite pede que cada participante traga um livro ou um jogo para a roda.|Lia só tem um jogo disponível.|Não há no convite exigência de levar os dois tipos.','Lia atende ao pedido levando apenas o jogo?','Sim, o pedido oferece alternativas.|Não, “ou” exige sempre os dois.|Não, jogos foram excluídos do convite.',[0,1,2],'Observe se as opções são alternativas ou exigências acumuladas.','Interpretar conectivos evita acrescentar condições que não foram escritas.'],
 ['A regra do caminho seco','O percurso curto está liberado somente se o piso estiver seco.|A equipe registrou água acumulada no piso nesta manhã.|O percurso longo está aberto independentemente desse trecho.','Qual caminho está liberado pelos registros?','O longo.|O curto, por ser mais rápido.|Ambos, porque é manhã.',[0,1,2],'Verifique se a condição da rota curta foi satisfeita.','Regras condicionais precisam ser comparadas com a situação observada.'],
 ['O salvo-conduto da chuva','O manual orienta guardar as cadeiras externas se houver previsão de chuva.|Mesmo sem previsão, devem ser guardadas quando a equipe observar chuva chegando.|Hoje não havia previsão, mas Lia viu a chuva se aproximar.','O que o manual orienta fazer?','Guardar as cadeiras pelo sinal observado.|Deixá-las fora porque a previsão não indicou chuva.|Guardar apenas se chuva e previsão coincidirem.',[0,1,2],'O manual apresenta uma segunda situação que exige agir.','Mais de uma condição pode levar à mesma orientação.']
 ]);
 addPhase(24,[
 ['O desenho dobrado','Lia trouxe um desenho para mostrar ao grupo.|Quando todos começaram a falar ao mesmo tempo, ela dobrou o papel e ficou perto da porta.|Nilo pediu silêncio e a convidou a explicar sua ideia; ela abriu o desenho novamente.','Qual interpretação é mais apoiada?','Lia precisava de espaço para ser ouvida.|Ela decidiu destruir o desenho.|Ela rejeitou qualquer conversa, mesmo após o convite.',[0,1,2],'Compare o recolhimento do papel e sua abertura após o convite.','Mudanças de comportamento ajudam a inferir necessidades e intenções.'],
 ['O lugar à sombra','Ravi tirou uma caixa do único banco à sombra quando a visitante chegou cansada.|Apontou o lugar livre e levou a caixa para o chão.|A visitante se sentou e agradeceu.','O gesto sugere que Ravi queria...','Oferecer um lugar confortável à visitante.|Impedir que ela descansasse.|Exigir que carregasse a caixa.',[0,1,2],'Observe quem se beneficia do lugar liberado.','A intenção provável deve ser ligada à sequência de ações.'],
 ['A pergunta adiada','Nilo levantou a mão durante a explicação da barqueira.|Ao perceber que ela ainda demonstrava um nó, abaixou a mão e esperou.|Quando a demonstração terminou, fez sua pergunta.','Por que ele provavelmente esperou?','Para não interromper a demonstração.|Porque havia esquecido a pergunta definitivamente.|Porque queria evitar aprender o nó.',[0,1,2],'O que ele faz após a demonstração?','Uma ação posterior pode esclarecer a intenção de uma espera.'],
 ['Um presente sem anúncio','Lia percebeu que o lápis de Ravi tinha acabado.|Deixou um lápis novo perto do caderno dele, sem interromper o trabalho.|Quando Ravi encontrou o objeto, ela apenas sorriu.','Qual leitura combina com as pistas?','Lia procurou ajudar discretamente.|Lia queria anunciar uma venda de lápis.|Lia retirou o caderno de Ravi.',[0,1,2],'Relacione a necessidade percebida com o objeto deixado.','Inferir intenções não exige uma fala explícita quando as ações oferecem pistas.'],
 ['O elogio e a revisão','Ravi elogiou o cartaz de Nilo e apontou que faltava o horário.|Nilo revisou o cartaz e agradeceu a observação.|Ravi ajudou a pendurá-lo na entrada.','Como entender a observação de Ravi?','Como uma contribuição para completar o cartaz.|Como prova de que o elogio era falso.|Como pedido para cancelar a atividade.',[0,1,2],'Uma sugestão pode coexistir com um elogio?','Um comentário de melhoria não apaga necessariamente uma avaliação positiva.']
 ]);
 addPhase(25,[
 ['A voz que sabe pouco','O narrador diz: “Eu estava no cais e vi Lia correr até o barco”.|Acrescenta: “Não ouvi o que ela disse à barqueira”.|Depois supõe que talvez Lia estivesse procurando uma caixa.','Qual limite o narrador reconhece?','Não conhece o conteúdo da conversa.|Não viu Lia no cais.|Sabe o motivo exato da corrida.',[0,1,2],'Separe ver uma ação, ouvir uma fala e supor um motivo.','Narradores podem indicar seus próprios limites de conhecimento.'],
 ['Os pensamentos de dois','A história conta que Lia ficou aliviada quando o barco chegou.|Também informa que Ravi temia perder a entrega, embora não dissesse isso.|Nenhum personagem ouviu uma confissão desses sentimentos.','O narrador apresenta...','Pensamentos de mais de um personagem.|Somente fatos que Lia contou em voz alta.|A opinião exclusiva de um vendedor.',[0,1,2],'Que informações internas o narrador oferece?','O acesso a pensamentos distingue perspectivas narrativas.'],
 ['O relatório e o diário','Relatório: “O grupo percorreu três trechos e voltou às onze”.|Diário de Nilo: “O trecho perto da gruta pareceu interminável; eu estava ansioso pela volta”.|Ambos descrevem a mesma caminhada.','Qual diferença se destaca?','O diário inclui uma experiência subjetiva; o relatório registra percurso e horário.|O diário prova que o trecho não tinha fim.|O relatório contém todos os sentimentos do grupo.',[0,1],'Compare medida registrada e sensação vivida.','Um mesmo fato pode ser relatado com foco factual ou pessoal.'],
 ['A versão do vencedor','Ravi narrou o jogo: “Foi uma partida fácil; marquei o ponto final”.|Lia lembrou que o placar esteve empatado até os últimos segundos.|O registro confirmou a vitória de Ravi por um ponto.','Como avaliar “fácil”?','É a avaliação de Ravi e não uma medida confirmada pelo placar.|É necessariamente a experiência de todos os jogadores.|Significa que não houve empate em nenhum momento.',[0,1,2],'O resultado confirma a vitória, mas confirma a avaliação?','Um fato comprovado não transforma toda avaliação do narrador em fato.'],
 ['Quem fica fora da história','O boletim descreveu apenas a montagem feita na oficina.|Não entrevistou quem transportou os materiais nem quem limpou o local.|Lia sugeriu incluir esses relatos para contar o trabalho completo.','O que a sugestão acrescenta?','Perspectivas de tarefas que o boletim deixou de fora.|Prova de que nada foi montado.|Uma nova data de inauguração.',[0,1,2],'Um relato pode ser correto e ainda incompleto?','Ampliar perspectivas pode tornar um relato mais completo sem negar o que já consta.']
 ]);
 addPhase(26,[
 ['Uma decisão precipitada','Nilo escolheu a trilha sem consultar o aviso de reparos.|Chegou ao trecho fechado e precisou voltar.|Lia chamou a decisão de precipitada.','O termo caracteriza uma decisão...','Tomada antes de considerar informações necessárias.|Comprovadamente segura por um teste.|Lenta por excesso de consultas.',[0,1,2],'Ligue a palavra ao modo como Nilo decidiu.','O contexto esclarece a avaliação de uma ação.'],
 ['Uma proposta viável','A equipe tinha material e tempo para montar duas mesas.|O projeto de Ravi exigia uma mesa; o de Nilo exigia dez.|Lia chamou o primeiro projeto de viável nas condições disponíveis.','“Viável” significa, aqui...','Possível de realizar com os recursos descritos.|Mais bonito segundo todos.|Já concluído antes da reunião.',[0,1,2],'Compare exigências e recursos, sem confundir possibilidade com execução.','Viabilidade descreve condições de realização, não a conclusão da obra.'],
 ['Um comentário incisivo','Na reunião, Lia apontou diretamente a falta de água no projeto.|Falou pouco, mas sua pergunta levou o grupo a revisar o plano.|O relato chamou o comentário de incisivo.','Qual sentido combina com “incisivo”?','Direto e capaz de atingir o ponto principal.|Sem relação com o projeto.|Necessariamente ofensivo a todas as pessoas.',[0,1,2],'Observe o conteúdo e o efeito da pergunta.','Ser direto não implica, por si só, agredir alguém.'],
 ['A reserva do conselho','O conselho recebeu um plano promissor, mas pediu mais testes.|O registro diz que aprovou a ideia com reservas.|A implantação completa ainda não foi autorizada.','O que “com reservas” indica?','Apoio acompanhado de cautela ou condições.|Compra de todos os assentos do barco.|Rejeição definitiva da ideia.',[0,1,2],'O texto trata de disponibilidade de lugares ou de cautela?','Uma expressão deve ser interpretada na relação com a decisão descrita.'],
 ['Uma passagem estreita','O mapa marca uma passagem estreita, por onde só uma pessoa cruza de cada vez.|Ravi sugeriu esperar antes de transportar uma caixa larga.|No mesmo relato, Lia diz que o tempo para a mudança também está apertado.','“Estreita” caracteriza principalmente...','A largura física da passagem.|A duração de toda a viagem.|A qualidade moral de quem passa.',[0,1],'Diferencie espaço limitado e tempo limitado.','Palavras próximas podem falar de dimensões distintas.']
 ]);
 addPhase(27,[
 ['A semente que espera','Poema: “Durmo sob terra escura”.|“Guardo um sol que ainda não nasceu”.|“Quando a chuva bate à porta, abro meus braços verdes”.','Qual imagem reúne melhor os versos?','Uma semente brotando, descrita com ações humanas.|Uma casa de pessoas com uma porta real.|Um relato técnico de construção.',[0,1,2],'Relacione terra, chuva e braços verdes.','As imagens de um poema devem ser lidas em conjunto.'],
 ['O bolso de lembranças','Nilo escreve: “Trago a vila no bolso”.|Logo depois, descreve um bilhete, uma pedra da praia e o cheiro de pão de que se lembra.|Ele havia viajado sem levar construções ou ruas.','O “bolso” representa principalmente...','Objetos e lembranças que ligam Nilo à vila.|Toda a vila fisicamente guardada.|A ausência de qualquer memória da viagem.',[0,1,2],'Que elementos aparecem junto à expressão figurada?','Objetos pequenos podem simbolizar experiências e afetos.'],
 ['A janela do poema','“Abri uma janela no medo”, diz o primeiro verso.|Os seguintes contam que a voz do poema pediu ajuda e encontrou companhia.|O texto não descreve uma reforma em casa.','A janela sugere...','Uma possibilidade de enfrentar o medo com apoio.|Uma abertura literal em uma parede mencionada.|Uma certeza de que o medo nunca voltará.',[0,1,2],'Relacione a imagem à mudança emocional narrada.','Uma imagem pode sugerir possibilidade sem prometer uma solução absoluta.'],
 ['O rio da espera','“A espera era um rio lento”.|A voz do poema conta que olhava o cais repetidas vezes antes da chegada de uma amiga.|Quando o barco chegou, diz que “as margens se aproximaram”.','Que sentido a imagem do rio constrói?','A percepção do tempo e da distância durante a espera.|Uma medição exata da velocidade da água.|A informação de que o cais mudou de lugar.',[0,1,2],'O poema mede um rio ou expressa uma experiência?','Imagens figuradas podem relacionar tempo, distância e sentimento.'],
 ['A luz que se reparte','No poema, uma lanterna passa de mão em mão.|“Minha luz não fica menor quando ilumino teu caminho”, diz a voz.|O último verso fala de aprender juntos na trilha.','Qual tema é sugerido pelo conjunto?','Compartilhar ajuda e conhecimento.|Vender uma lanterna com duração comprovada.|Impedir outras pessoas de aprender.',[0,1,2],'Observe a partilha e a aprendizagem mencionada no final.','Símbolos podem representar relações humanas além do objeto descrito.']
 ]);
 addPhase(28,[
 ['Uma receita com aviso','A página lista ingredientes e apresenta etapas numeradas para preparar tinta de terra.|Ao final, orienta esperar a mistura esfriar antes de manusear.|Não relata quem já preparou a tinta.','A finalidade principal é...','Orientar um procedimento com cuidados.|Narrar uma experiência passada de Nilo.|Anunciar uma votação.',[0,1],'Lista e etapas organizam qual ação do leitor?','A estrutura ajuda a reconhecer a função de um gênero textual.'],
 ['Uma carta de agradecimento','A carta começa com uma saudação à barqueira.|Lia agradece por ela ter esperado o grupo durante a chuva e encerra com uma despedida.|Não apresenta horários de viagens futuras.','O texto procura principalmente...','Expressar gratidão por uma ajuda recebida.|Fixar uma tabela de partidas.|Comprovar a lotação de todos os barcos.',[0,1],'Observe o destinatário e a intenção das palavras.','A finalidade de uma carta depende da situação comunicativa.'],
 ['O diário não é manual','Nilo escreve: “Hoje tentei montar a mesa e troquei dois encaixes”.|Conta como se sentiu ao pedir ajuda.|Não oferece uma lista completa de peças ou instruções para outra pessoa.','Qual uso combina melhor com o texto?','Conhecer a experiência pessoal de Nilo.|Usá-lo como manual completo de montagem.|Tratá-lo como orçamento de materiais.',[0,1,2],'O texto conta uma vivência ou orienta todas as etapas?','Conhecer o gênero ajuda a não exigir informações que ele não pretende oferecer.'],
 ['A ata da reunião','O documento registra data, participantes e decisões do conselho.|Informa que a escolha do banco ficou pendente até a próxima visita técnica.|Não reproduz toda a conversa.','Qual função o documento cumpre?','Registrar oficialmente encaminhamentos da reunião.|Garantir aprovação de qualquer proposta citada.|Contar uma aventura com final inventado.',[0,1,2],'Registro de encaminhamento é diferente de transcrição integral.','Uma ata seleciona informações relevantes sobre decisões e pendências.'],
 ['O conto da concha','A história apresenta uma concha que conversa com as ondas.|Os personagens descobrem um caminho imaginário e voltam transformados pela aventura.|Não há indicação de observação científica.','Como ler esse texto?','Como narrativa ficcional com acontecimentos imaginados.|Como prova científica de que conchas falam.|Como tabela de horários do mar.',[0,1,2],'Que pistas indicam construção de um mundo imaginário?','Identificar ficção evita transformar imagens narrativas em comprovação factual.']
 ]);
 addPhase(29,[
 ['O título que exagerou','Título: “Toda a vila ficou sem água”.|A notícia informa que o depósito oeste ficou sem abastecimento por uma hora.|As casas e a horta mantiveram água, segundo o mesmo texto.','Qual título seria mais fiel?','Depósito oeste teve interrupção de uma hora.|A ilha perdeu toda a água para sempre.|Nenhum lugar teve interrupção.',[0,1,2],'Compare o alcance do título com o que a notícia relata.','Títulos precisam respeitar lugar, duração e alcance das informações.'],
 ['Uma notícia e sua data','Um recorte relata reparo na ponte na semana passada.|Uma atualização de hoje informa que a ponte foi vistoriada e reaberta.|A legenda do recorte foi compartilhada sem a data.','O que falta na mensagem compartilhada?','Contexto temporal que evita parecer uma interdição atual.|Prova de que o reparo nunca ocorreu.|Um novo nome para a ponte.',[0,1,2],'Uma notícia antiga pode ser verdadeira e ainda induzir erro?','O contexto temporal importa mesmo quando a informação original é verdadeira.'],
 ['A fala entre aspas','A notícia diz: “O teste foi promissor”, afirmou Lia.|Depois informa que a equipe ainda não terminou a avaliação.|O título diz apenas “Teste concluído”.','Qual leitura distingue as informações?','Lia fez uma avaliação inicial; a notícia não confirma conclusão do teste.|Promissor significa obrigatoriamente concluído.|As aspas tornam a fala uma garantia universal.',[0,1,2],'Compare opinião citada e situação registrada.','Uma citação atribuída não substitui a descrição do estágio de um processo.'],
 ['O que a imagem mostra','A imagem mostra três pessoas na fila da biblioteca.|A legenda afirma que ninguém visitou a feira naquela manhã.|Não se sabe quando a foto foi feita nem onde fica a feira em relação à biblioteca.','A imagem comprova a legenda?','Não: local, momento e assunto não sustentam essa conclusão.|Sim: três pessoas na biblioteca provam ausência na feira.|Sim: toda foto representa a manhã inteira.',[0,1,2],'A foto registra a situação que a legenda afirma?','Uma imagem precisa de contexto pertinente para sustentar uma afirmação.'],
 ['A pergunta do repórter','O boletim ouviu só organizadores sobre a inauguração.|Todos disseram que a montagem funcionou bem.|Lia sugeriu ouvir também visitantes sobre circulação e espera.','Por que incluir visitantes?','Para investigar aspectos da experiência que os organizadores não cobriram.|Para garantir que todos discordarão.|Para apagar os registros da montagem.',[0,1,2],'Que perguntas continuam sem resposta?','Mais fontes podem ampliar o foco sem invalidar automaticamente as anteriores.']
 ]);
 addPhase(30,[
 ['O registro da semana','Em quatro dias, a oficina recebeu 6, 4, 7 e 3 visitantes.|O relatório soma 20 visitas, sem identificar pessoas repetidas.|Nilo escreveu que foram 20 moradores diferentes.','Qual conclusão respeita o registro?','Foram registradas 20 visitas; não sabemos quantas pessoas distintas.|Foram comprovados 20 moradores distintos.|Cada visita pertence necessariamente à mesma pessoa.',[0,1,2],'Visitas e visitantes únicos são a mesma medida?','Defina a unidade contada antes de interpretar um total.'],
 ['Duas filas, duas medidas','Na biblioteca, o registro conta oito pessoas esperando.|No porto, informa dez minutos de espera média.|Ravi diz que a fila da biblioteca é mais lenta por ter um número maior.','O que impede essa comparação direta?','Os números medem coisas diferentes: pessoas e tempo.|Oito é sempre maior que qualquer duração.|A biblioteca não pode ter fila.',[0,1,2],'Compare as unidades antes de comparar os números.','Números só são diretamente comparáveis quando a medida é compatível.'],
 ['A caixa que voltou','Inventário inicial: nove lanternas disponíveis.|Três foram emprestadas; uma delas voltou antes da reunião.|O conselho precisa de sete lanternas ao mesmo tempo.','Qual situação deve ser comunicada?','Há sete disponíveis, considerando empréstimos e devolução.|Há nove disponíveis, ignorando os empréstimos.|Há seis, ignorando a devolução.',[0,1,2],'Atualize o registro com saídas e retornos.','Interpretar registros envolve acompanhar mudanças, não apenas ler o primeiro total.'],
 ['Uma média não é promessa','Em três travessias, os tempos foram 10, 12 e 14 minutos.|A barqueira informa média de 12 minutos naquele conjunto.|O aviso também diz que vento e carga podem alterar a duração.','A média garante que a próxima viagem durará 12 minutos?','Não: resume essas viagens e não fixa o tempo da próxima.|Sim: médias eliminam variações.|Não: a média registrada deve ser 36 minutos.',[0,1,2],'Diferencie resumo de observações e previsão garantida.','Uma média descreve um conjunto sem assegurar o resultado de cada caso futuro.'],
 ['O estoque reservado','O registro indica 15 caixas de papel.|Cinco estão reservadas para a escola e não entram na distribuição da feira.|Nilo quer separar 12 para a feira.','Qual ajuste respeita os registros?','Considerar no máximo dez caixas disponíveis para a feira.|Usar as 15 porque todas estão no depósito.|Separar 12 sem alterar nenhuma reserva.',[0,1,2],'Disponível fisicamente significa livre para qualquer finalidade?','Uma reserva modifica a quantidade utilizável para uma decisão.']
 ]);
 addPhase(31,[
 ['Quem respondeu à consulta','A oficina perguntou aos visitantes de sábado se queriam jogos à tarde.|A maioria respondeu sim.|O relatório chama isso de preferência de toda a vila, inclusive de quem não visitou a oficina.','Qual limite deve ser reconhecido?','A consulta representa os respondentes, não necessariamente toda a vila.|A maioria dos visitantes prova a preferência de todos.|Não houve nenhuma resposta válida.',[0,1,2],'Quem foi ouvido e quem ficou fora da consulta?','Uma amostra limita o alcance de uma conclusão sobre um grupo maior.'],
 ['O teste com duas diferenças','A planta A recebeu mais água e ficou ao sol.|A planta B recebeu menos água e ficou à sombra.|A cresceu mais; Ravi atribuiu toda a diferença apenas à água.','Por que a atribuição é limitada?','Água e iluminação mudaram juntas.|Nenhuma planta recebeu água.|Crescimento prova que sombra sempre impede vida.',[0,1,2],'Qual outra condição também foi alterada?','Quando várias condições mudam juntas, fica difícil isolar uma causa.'],
 ['As canecas escolhidas','Para avaliar as canecas novas, Nilo testou apenas as duas sem rachaduras visíveis.|O lote também tinha outras com defeitos que não foram examinadas.|Ele afirmou que todo o lote era resistente.','Qual problema existe na conclusão?','A escolha deixou de fora peças que poderiam ter outro desempenho.|Duas peças boas provam o resultado de todas.|Defeitos visíveis provam que nenhuma peça funciona.',[0,1,2],'A seleção representa o conjunto que a conclusão menciona?','Uma seleção favorável pode distorcer a avaliação do conjunto.'],
 ['Antes e depois do banco','A praça recebeu um banco e uma cobertura na mesma semana.|Depois, mais pessoas passaram a permanecer no local.|O relatório não separa o efeito de cada mudança.','O que podemos concluir com cuidado?','A permanência aumentou após as mudanças, sem isolar o efeito do banco.|Só o banco causou todo o aumento.|A cobertura não teve nenhum efeito, com certeza.',[0,1,2],'O registro isolou cada alteração?','Um resultado posterior pode ser compatível com várias explicações.'],
 ['Uma comparação mais justa','A equipe quer comparar duas lanternas.|Propõe usar cada uma com a mesma carga, pelo mesmo tempo e na mesma sala.|Também anotará resultados de mais de uma unidade de cada modelo.','Por que esse plano melhora a comparação?','Reduz diferenças de condições e considera variação entre unidades.|Garante que os resultados serão iguais.|Elimina a necessidade de registrar o teste.',[0,1,2],'Que fatores o plano procura manter semelhantes?','Comparações cuidadosas controlam condições e registram diferenças reais.']
 ]);
 addPhase(32,[
 ['O convite e a suposição','Lia convidou Ravi para apresentar um projeto.|Nilo concluiu que o convite provava aprovação do conselho.|O aviso da reunião diz que os projetos ainda serão discutidos.','Qual suposição de Nilo não tem apoio?','Que ser convidado a apresentar significa já estar aprovado.|Que Ravi recebeu um convite.|Que haverá uma reunião.',[0,1,2],'Apresentar e aprovar são etapas diferentes?','Identifique a ideia acrescentada sem evidência entre um fato e uma conclusão.'],
 ['A ponte e o caminho vazio','Nilo viu o caminho vazio às sete e pensou que a ponte estivesse fechada.|O horário de maior movimento começa às nove.|Não consultou o aviso da travessia.','O que falta para sustentar sua conclusão?','Verificar o estado da ponte, em vez de inferi-lo apenas do movimento.|Provar que caminhos sempre têm pessoas às sete.|Confirmar a cor do mapa.',[0,1,2],'Outra explicação combina com o caminho vazio?','Uma observação pode ter mais de uma explicação compatível.'],
 ['O bilhete sem resposta','Ravi enviou uma pergunta e não recebeu resposta em dez minutos.|Lia estava conduzindo a barca e só leria recados no porto.|Ravi pensou que ela não quisesse ajudar.','Qual leitura considera o contexto?','A demora pode decorrer da tarefa de Lia, sem provar recusa.|Dez minutos sempre provam recusa.|A ausência de resposta comprova que o recado foi lido.',[0,1,2],'Não responder ainda significa ter lido e rejeitado?','Uma interpretação precisa considerar acesso e situação antes de atribuir intenção.'],
 ['Um objeto na mochila','Lia viu uma ferramenta da oficina na mochila de Nilo.|Nilo mostrou o registro do empréstimo autorizado naquela manhã.|A ferramenta deveria ser devolvida no fim do dia.','O registro corrige qual interpretação?','A de que estar na mochila provava uma retirada não autorizada.|A de que a ferramenta era da oficina.|A de que havia um prazo de devolução.',[0,1,2],'A presença do objeto informa, sozinha, se houve autorização?','Documentos podem resolver uma suposição sobre a legitimidade de uma ação.'],
 ['Uma proposta alternativa','Ravi sugeriu pintar os bancos, e Lia apresentou a possibilidade de repará-los primeiro.|Nilo disse que Lia era contra qualquer melhoria.|Ela explicou que a pintura duraria melhor após o reparo.','Que suposição precisa ser revista?','Que propor outra sequência significa rejeitar toda melhoria.|Que os bancos podem ser pintados.|Que Lia propôs uma etapa anterior.',[0,1,2],'Uma alternativa pode apoiar o objetivo com outro caminho?','Discordar do meio não equivale necessariamente a rejeitar o objetivo.']
 ]);
 addPhase(33,[
 ['Uma objeção relevante','Proposta: ampliar a feira no corredor central.|Lia observa que ele é a única passagem para a rampa e pede medir a largura livre.|Nilo responde apenas que a feira será bonita.','Qual resposta enfrenta a objeção?','Verificar a circulação e ajustar a disposição das barracas.|Repetir que as barracas são bonitas.|Dizer que toda objeção impede festas.',[0,1,2],'A objeção trata de beleza ou de acesso?','Um contra-argumento precisa ser respondido no ponto que ele apresenta.'],
 ['Um caso contrário','Nilo afirma que nenhum morador usa a biblioteca à noite.|Lia apresenta três registros de empréstimos noturnos identificados.|Os registros não indicam o movimento de todas as noites.','O que os registros permitem contestar?','A afirmação de que ninguém usa à noite.|Afirmar que todas as noites são lotadas.|Dizer que a biblioteca abre o dia todo.',[0,1,2],'Que palavra absoluta é contrariada pelos exemplos?','Um contraexemplo pode derrubar uma afirmação universal sem provar o extremo oposto.'],
 ['O motivo não é a pessoa','Ravi propôs reutilizar caixas para a exposição.|Nilo rejeitou porque Ravi errou uma medida na semana anterior.|Não examinou se as caixas tinham tamanho e resistência adequados.','Qual avaliação seria mais pertinente?','Examinar as caixas e os requisitos da exposição.|Rejeitar qualquer proposta futura de Ravi.|Aprovar sem verificar por simpatia.',[0,1,2],'A crítica examina a proposta atual?','Avaliar uma ideia exige argumentos sobre ela, não só julgamentos sobre quem a propôs.'],
 ['A resposta que reconhece limites','Lia propõe uma cobertura para reduzir bancos molhados.|Ravi pergunta se ela protegerá da chuva com vento forte.|Lia sugere testar essa condição antes de ampliar a instalação.','Como a resposta de Lia fortalece o debate?','Reconhece a dúvida e propõe investigação pertinente.|Garante proteção total sem testar.|Declara que a pergunta não importa.',[0,1,2],'Ela responde à dúvida com promessa ou teste?','Reconhecer um limite pode melhorar a justificativa de uma proposta.'],
 ['Duas opções não são todas','O mural diz: “Ou fechamos a praça ou aceitamos lixo em toda parte”.|O conselho também discute lixeiras e equipes de cuidado.|A praça continua usada para encontros.','Qual limite há na frase do mural?','Apresenta só dois extremos, omitindo alternativas em discussão.|Demonstra que lixeiras são impossíveis.|Confirma que a praça já fechou.',[0,1,2],'Existem alternativas além dos extremos citados?','Um debate pode ser distorcido quando alternativas reais são omitidas.']
 ]);
 addPhase(34,[
 ['A mensagem encaminhada','Um recado circulou: “A oficina cancelou todas as aulas”.|Não tinha data nem assinatura.|No mural oficial, a oficina informou o cancelamento de uma aula de terça, mantendo as demais.','O que fazer antes de compartilhar?','Consultar a informação identificada e preservar seu alcance.|Repassar a frase mais ampla por ser urgente.|Remover a data do mural para simplificar.',[0,1,2],'Qual fonte informa o que foi realmente cancelado?','Verificar autoria, data e alcance reduz distorções ao compartilhar.'],
 ['O áudio cortado','No áudio completo, Lia diz: “A ponte não estará aberta amanhã, se a revisão não terminar”.|A versão curta deixa apenas “A ponte não estará aberta amanhã”.|A revisão ainda está em andamento.','O que o corte altera?','Retira a condição e faz a fala parecer uma previsão sem ressalva.|Acrescenta uma condição mais específica.|Prova que a revisão foi concluída.',[0,1,2],'Que relação desapareceu na versão curta?','Cortar uma condição pode mudar a força de uma afirmação.'],
 ['A imagem reutilizada','Uma foto de caixas molhadas foi feita na tempestade do mês passado.|Hoje foi compartilhada como imagem da entrega desta manhã.|O recibo de hoje registra que as caixas chegaram secas.','Qual problema precisa ser corrigido?','A foto foi associada a outro momento, sem contexto correto.|A foto prova o estado de toda entrega futura.|Um recibo nunca pode mencionar condições de entrega.',[0,1,2],'A imagem corresponde ao evento anunciado?','Uma imagem autêntica pode ser usada de forma enganosa fora de contexto.'],
 ['Muitas cópias, uma origem','Cinco cartazes repetem a mesma afirmação sobre um cristal.|Todos copiaram o anúncio da loja, sem teste independente.|Nilo contou os cartazes como cinco confirmações diferentes.','Por que essa contagem não fortalece a prova?','As cópias dependem da mesma origem.|Cada cópia realiza automaticamente um novo teste.|Cartazes não podem conter nenhuma informação verdadeira.',[0,1,2],'As fontes são realmente independentes?','Repetição de uma afirmação não equivale a confirmações independentes.'],
 ['A correção visível','O boletim publicou horário errado para a assembleia.|Na atualização, identificou o erro, apresentou o horário correto e manteve a data da correção.|Lia consultou a atualização antes de sair.','Que prática ajuda o leitor?','Tornar a correção identificável e atualizar a informação.|Apagar qualquer indicação de que houve alteração.|Deixar as duas horas sem explicar qual vale.',[0,1,2],'O leitor consegue reconhecer a informação mais recente?','Correções transparentes ajudam a acompanhar mudanças e avaliar uma fonte.']
 ]);
 addPhase(35,[
 ['Só até o pôr do sol','O anúncio oferece desconto para comprar sementes até o pôr do sol.|Afirma que adiar seria “perder a única chance de ter um jardim”.|O catálogo da vila também oferece sementes em outros dias.','Qual recurso o anúncio usa?','Pressão de urgência, ampliando o sentido de uma oferta temporária.|Prova de que jardins só podem começar hoje.|Uma comparação independente de todas as sementes.',[0,1,2],'O prazo do desconto é o prazo de qualquer possibilidade de plantar?','Uma oferta temporária pode ser apresentada como uma necessidade exagerada.'],
 ['O brinde e o preço','A loja anuncia uma caneca de brinde na compra de uma lanterna.|O preço final da lanterna está informado separadamente.|Lia quer saber se a compra atende à necessidade de iluminar a trilha.','O que deve orientar a decisão?','Preço e desempenho para a necessidade, além do atrativo do brinde.|Somente a existência da caneca.|A certeza de que todo brinde torna a compra vantajosa.',[0,1,2],'O brinde responde à necessidade principal?','Elementos atraentes não substituem a avaliação do produto e do custo.'],
 ['O depoimento do amigo','Ravi gostou de uma mochila em uma caminhada curta.|O anúncio usa seu depoimento para afirmar conforto em qualquer jornada.|Não apresenta outros usos ou condições de carga.','Qual limite há na promessa?','Amplia uma experiência específica para todos os usos.|O depoimento comprova todas as cargas possíveis.|A mochila não pode ter sido confortável para Ravi.',[0,1,2],'Um relato de experiência cobre todos os cenários anunciados?','Um depoimento pode ser verdadeiro e insuficiente para uma promessa ampla.'],
 ['O selo sem explicação','A embalagem diz “Qualidade superior” e mostra um selo desenhado.|Não identifica critérios, avaliador ou comparação.|A oficina oferece testar encaixe e resistência antes de comprar peças.','O que fornece informação mais útil?','Um teste com critérios claros relacionados ao uso.|O tamanho do selo desenhado.|A palavra superior, sem outra informação.',[0,1,2],'Que dado permitiria conferir a afirmação?','Avaliações precisam de critérios identificáveis, não apenas aparência de autoridade.'],
 ['Uma escolha com alternativas','Lia precisa de uma lanterna por uma noite.|A loja só anuncia compra, mas a oficina também oferece empréstimo com devolução.|Ambas as opções estão disponíveis no mesmo dia.','Qual avaliação considera melhor a situação?','Comparar compra e empréstimo para o uso de uma noite.|Comprar porque o anúncio só mostrou essa opção.|Concluir que empréstimo significa propriedade definitiva.',[0,1,2],'A opção anunciada é necessariamente a única?','Decidir com autonomia inclui procurar alternativas pertinentes.']
 ]);
 addPhase(36,[
 ['Provável não é certo','Duas pistas apontam que Lia passou pela gruta: sua capa está lá e o diário registra uma visita com suas iniciais.|O grupo ainda não falou com ela.|Ravi diz que a passagem é provável.','Qual formulação respeita a certeza disponível?','As pistas sugerem que Lia passou por lá; ainda falta confirmação.|Foi provado tudo o que Lia fez na gruta.|As pistas não permitem nenhuma hipótese.',[0,1,2],'Compare indícios e confirmação direta.','O grau de certeza deve acompanhar a força das evidências.'],
 ['A explicação possível','O sino não tocou, e a corda parecia frouxa.|O técnico disse que a corda poderia explicar a falha, mas precisaria examinar o mecanismo.|Nenhum diagnóstico final foi registrado.','Como comunicar a situação?','Há uma hipótese sobre a corda, ainda em investigação.|A causa foi definitivamente comprovada.|O sino não pode ter qualquer defeito.',[0,1,2],'Que palavra marca uma possibilidade?','Relatar uma hipótese como hipótese evita transformar uma possibilidade em certeza.'],
 ['O que foi descartado','A equipe suspeitou de falta de energia no painel.|O teste confirmou energia na entrada, mas não examinou todas as peças internas.|Continuou investigando o motivo de a luz não acender.','O que o teste permite dizer?','A falta de energia na entrada foi descartada, não todos os defeitos.|O painel inteiro está necessariamente perfeito.|Nenhuma peça pode funcionar.',[0,1,2],'Qual parte exata foi testada?','Eliminar uma explicação específica não resolve automaticamente todo o problema.'],
 ['Não observado ainda','A oficina não observou falhas em três usos da ferramenta.|O relatório informa que ela ainda não foi usada sob chuva.|Ravi quer afirmar que falhas na chuva são impossíveis.','Qual registro é mais cuidadoso?','Não houve falhas nos usos observados; a condição de chuva continua sem teste.|Falhas são impossíveis em qualquer condição.|Três usos sem falha provam que a chuva causará defeito.',[0,1,2],'A condição da conclusão foi observada?','Ausência de falha em um contexto não comprova ausência em todos os contextos.'],
 ['Uma dúvida delimitada','O conselho sabe que a ponte suporta o grupo pequeno testado.|Não sabe se suporta o veículo mais pesado previsto para a feira.|O relatório pede teste adequado a essa carga.','Qual pergunta concentra a dúvida relevante?','A ponte atende à carga do veículo previsto?|A ponte existe?|O grupo pequeno já atravessou, fato registrado?',[0,1,2],'O que já sabemos e o que falta saber?','Delimitar a dúvida evita repetir perguntas respondidas ou ampliar demais a incerteza.']
 ]);
 addPhase(37,[
 ['A praça em dois horários','O grupo de leitura precisa de silêncio às nove.|A equipe de música ensaia às onze e quer usar a mesma praça.|A agenda não registra outro uso nesse intervalo.','Qual proposta considera os objetivos?','Organizar usos em horários distintos e combinar a transição.|Proibir para sempre uma das atividades.|Marcar ambas às nove sem discutir som.',[0,1,2],'As necessidades podem ser conciliadas pelo horário?','Negociar pode mudar a organização sem apagar um dos objetivos.'],
 ['Um corredor com limites','A feira precisa de mesas; visitantes precisam alcançar a rampa.|A planta permite mesas junto às paredes, mantendo o corredor livre.|A proposta inicial ocupava a passagem central.','Qual ajuste atende aos dois interesses?','Distribuir mesas nas laterais e preservar a passagem.|Manter mesas no centro e pedir que ninguém use a rampa.|Eliminar a feira sem analisar a planta.',[0,1,2],'Localize espaço disponível e função da passagem.','Uma solução compartilhada deve considerar condições concretas e acesso.'],
 ['O orçamento da horta','A verba permite comprar ferramentas ou construir uma cobertura completa, mas não ambos.|A equipe já tem algumas ferramentas emprestadas; a chuva tem impedido o armazenamento.|O conselho quer definir prioridades sem ignorar necessidades futuras.','Qual encaminhamento é mais fundamentado?','Avaliar a cobertura e o uso temporário dos empréstimos, registrando a necessidade de ferramentas.|Dizer que nenhuma ferramenta será necessária novamente.|Comprar tudo como se o limite não existisse.',[0,1,2],'Considere recursos atuais, problema imediato e o que permanece pendente.','Priorizar não significa negar a existência das necessidades adiadas.'],
 ['O descanso e a passagem','Moradores pedem bancos na trilha.|A equipe informa que o trecho estreito precisa ficar livre, mas há dois pontos largos com sombra.|A proposta inicial não escolhia locais específicos.','Qual mudança melhora o plano?','Considerar os pontos largos sem bloquear o trecho estreito.|Instalar bancos em toda a largura do trecho estreito.|Concluir que nenhuma parte da trilha comporta descanso.',[0,1,2],'Uma restrição local impede todas as alternativas?','Restrições podem orientar a busca de locais adequados em vez de inviabilizar todo o plano.'],
 ['A decisão que será revista','O conselho autorizou testar uma feira menor por duas semanas.|Combinou avaliar circulação, participação e sobras antes de ampliar.|A ata não chama a decisão de definitiva.','Qual leitura respeita o combinado?','É uma experiência com critérios e possibilidade de revisão.|A ampliação total já foi aprovada.|A feira foi cancelada para sempre.',[0,1,2],'Observe prazo e avaliação prevista.','Decisões provisórias podem produzir informações para escolhas posteriores.']
 ]);
 addPhase(38,[
 ['A pergunta antes do teste','Ravi quer descobrir se uma nova cobertura mantém o banco seco na chuva.|Nilo propõe apenas medir a altura do banco.|Lia sugere observar a superfície protegida durante chuva e comparar com uma sem cobertura.','Qual investigação responde melhor à pergunta?','A observação na chuva com comparação pertinente.|Somente a altura do banco.|Contar quantas pessoas gostam da cor.',[0,1,2],'O procedimento mede o efeito que queremos conhecer?','Uma investigação começa alinhando pergunta, observação e critério.'],
 ['O registro que precisa de detalhe','A equipe testou a lanterna e escreveu apenas “funcionou”.|O conselho quer saber por quanto tempo e em qual distância o sinal era visível.|Lia pede anotar duração, distância e condições do teste.','Por que detalhar o registro?','Para relacionar o resultado às perguntas e às condições de uso.|Para garantir sucesso em qualquer situação.|Para substituir o teste por opiniões.',[0,1,2],'“Funcionou” responde a todas as perguntas do conselho?','Registros úteis descrevem condições e medidas que permitem interpretar o resultado.'],
 ['Um resultado inesperado','No primeiro teste, a caixa de Ravi resistiu menos que a de Lia.|A equipe percebeu que uma caixa recebeu carga dobrada.|Antes de concluir, propôs repetir a comparação com cargas iguais.','O que justifica a repetição?','Uma diferença nas condições impede atribuir o resultado apenas às caixas.|O resultado deve ser apagado por desagradar a Ravi.|Toda repetição precisa produzir empate.',[0,1,2],'Qual condição não foi semelhante?','Repetir com condições comparáveis pode esclarecer um resultado, preservando o registro anterior.'],
 ['A hipótese que não se confirmou','A equipe suspeitava que o atraso vinha do caminho mais longo.|Os registros mostraram atrasos também no caminho curto, nos dias de espera por carga.|Lia sugeriu investigar a preparação da carga.','Qual próximo passo usa melhor os registros?','Examinar a espera por carga como outra explicação possível.|Manter a hipótese inicial sem considerar os dados.|Garantir que o caminho nunca influencia viagens.',[0,1,2],'Que padrão novo aparece nos registros?','Uma hipótese pode ser revista sem transformar a alternativa em certeza antes de investigar.'],
 ['O critério combinado','O conselho quer testar se uma placa ajuda visitantes a encontrar a biblioteca.|Antes do teste, combina contar quantos chegam sem pedir orientação e comparar períodos semelhantes.|Também registrará mudanças na entrada ou no percurso.','Qual vantagem desse plano?','Define um critério e observa fatores que podem afetar a comparação.|Garante que qualquer placa será eficaz.|Elimina a necessidade de ouvir os visitantes.',[0,1,2],'Como o grupo reconhecerá uma melhora?','Critérios prévios tornam a avaliação mais clara e ajudam a reconhecer limites.']
 ]);
 addPhase(39,[
 ['O caminho de três documentos','Mapa: a rota leste chega à escola por uma rampa; a oeste inclui escadas.|Aviso da manutenção: a rampa leste ficará fechada até sexta.|Convite: a roda de leitura será quinta e deve permitir chegada de visitantes com rodas.|A escola aceita mudar a data, mas não concluiu o reparo.','Qual recomendação considera todos os documentos?','Negociar uma data após a liberação confirmada da rampa, preservando o acesso.|Manter quinta usando escadas como se todos pudessem utilizá-las.|Afirmar que a rampa já está aberta porque aparece no mapa.',[0,1,2,3],'Combine rota, estado atual, data e necessidade de acesso.','Uma síntese responsável verifica se as condições do plano podem ser atendidas.'],
 ['Uma conclusão com três limites','O relatório conta que uma turma gostou da oficina em uma tarde.|O convite comercial usa isso para prometer aprendizagem completa a qualquer criança.|A avaliação não mediu leitura antes ou depois nem acompanhou outros grupos.|Lia propõe continuar observando participação e aprendizagem com critérios claros.','Qual resposta crítica é melhor fundamentada?','O gosto relatado é um dado da turma; não prova aprendizagem completa para todos.|O entusiasmo comprova domínio total de leitura.|A falta de avaliação prova que nenhuma criança aprendeu nada.',[0,1,2],'Diferencie gostar, aprender e garantir resultados universais.','Avalie exatamente o que a evidência mede e o alcance da promessa.'],
 ['A assembleia e a frase bonita','Uma proposta quer iluminar a praça com cristais.|O poema da inauguração diz: “Nossa noite nunca mais terá sombra”.|O teste iluminou o centro, mas deixou partes das laterais escuras.|A equipe sugere ajustar a posição e medir novas áreas antes de prometer cobertura total.','Como relacionar poema e registro?','A imagem poética celebra a ideia; o teste ainda limita a afirmação sobre cobertura.|O poema comprova tecnicamente toda a iluminação.|O teste nas laterais prova que o centro também permaneceu escuro.',[1,2,3],'Não use linguagem figurada como medida técnica.','Gêneros distintos podem falar da mesma proposta com funções e critérios diferentes.'],
 ['O arquivo das versões revisadas','Versão de segunda: a exposição seria no pátio, com entrada às dez.|Atualização de quarta, assinada pela escola: passou para o salão às onze por causa da chuva.|Uma mensagem de quinta repete a versão de segunda sem citar a atualização.|Lia quer orientar quem vai à exposição sem ampliar o boato.','Qual mensagem deve enviar?','Informar salão às onze, citando a atualização da escola e a mudança.|Repetir pátio às dez porque a mensagem circulou por último.|Garantir que a exposição foi cancelada, embora isso não conste.',[0,1,2,3],'A mensagem mais recente contém a informação atualizada ou apenas uma cópia antiga?','Data de compartilhamento e data da informação podem ser diferentes.'],
 ['O horizonte de todas as vozes','Relato dos visitantes: “Precisamos de um caminho com passagem livre e sinais que possamos entender”.|Planta da vila: a rota junto ao jardim comporta uma passagem larga; a rota da gruta inclui degraus e um trecho estreito.|Equipe de construção: “Podemos sinalizar o jardim, mas falta testar a leitura das placas com visitantes e conferir o piso após chuva”.|Anúncio no mural: “Nosso caminho será perfeito para qualquer pessoa em qualquer dia!”.|O conselho dispõe de recursos para um trecho piloto e quer ouvir os visitantes antes de expandir.','Qual recomendação integra melhor necessidades, recursos e limites?','Construir um trecho piloto pelo jardim, testar placas e piso com visitantes e revisar antes de expandir, sem prometer perfeição universal.|Abrir toda a rota da gruta e tratar o anúncio como prova de acesso para todos.|Abandonar qualquer melhoria porque ainda existem aspectos a testar.',[0,1,2,4],'Relacione necessidade, percurso possível, testes pendentes e recursos do conselho.','Interpretar com autonomia: construa uma recomendação apoiada por fontes e reconheça o que precisa ser investigado.','O anúncio não comprova acessibilidade; a rota da gruta apresenta obstáculos registrados.','Testes pendentes indicam o que investigar, não a certeza de fracasso.']
 ]);
 // O instalador recebe phase(), que guarda os novos desafios no mesmo conjunto.
}
if(typeof module!=='undefined')module.exports=extendCampaign;
else{extendCampaign(REGIONS,phase);MISSIONS.at(-1).reflection='Escreva sua recomendação ao conselho. Relacione pelo menos duas fontes e explique o que ainda precisa ser testado.';if(MISSIONS.length!==200||new Set(MISSIONS.map(m=>m.id)).size!==200)throw new Error('A campanha deve conter duzentas casas distintas.');}
